  void startTimer() {
    const oneSec = const Duration(seconds: 1);
    _timer = new Timer.periodic(
      oneSec,
      (Timer timer) {
        if (_start == 0) {
          setState(() {
            timer.cancel();
          });
          print("_start : $_start");
        } else {
          setState(() {
            _start--;
          });
          print("_start : $_start");
        }
      },
    );
  }

  // get layout
  getLayout() async {
    var request = http.Request(
        'GET', Uri.parse('${Variables.ipv4_local}/api/layout-kostum'));
    var streamedResponse = await request.send();
    var response = await http.Response.fromStream(streamedResponse);
    if (response.statusCode == 200) {
      final result = jsonDecode(response.body) as List<dynamic>;
      layouts.addAll(result);
      for (var element in layouts) {
        if (element['status'] == 'Aktif') {
          print("object : ${element['nama']}");
        }
      }
    } else {
      print(response.reasonPhrase);
    }
  }

  getSettings() async {
    db.getConnection().then(
      (value) {
        String sql = "select * from `settings`";
        value.query(sql).then((value) {
          for (var row in value) {
            setState(() {
              string_logo = row[7];
            });
          } // Finally, close the connection
        }).then((value) => print("object string logo : $string_logo"));
        return value.close();
      },
    );
  }

  // get background from api
  getBackground() async {
    var request = http.Request(
        'GET', Uri.parse('${Variables.ipv4_local}/api/background'));
    var streamedResponse = await request.send();
    var response = await http.Response.fromStream(streamedResponse);
    if (response.statusCode == 200) {
      final result = jsonDecode(response.body) as List<dynamic>;
      background.addAll(result);
    } else {
      print(response.reasonPhrase);
    }
  }

  getWarnaBg() async {
    db.getConnection().then(
      (value) {
        String sql = "select * from `main_color`";
        value.query(sql).then((value) {
          for (var row in value) {
            setState(() {
              bg_warna_main = row[1];
              warna1 = row[2];
              warna2 = row[3];
            });
          } // Finally, close the connection
        }).then((value) {
          // ...
          print("bg main color : $bg_warna_main");
          print("bg main color : $warna1");
          print("bg main color : $warna2");
        });
        return value.close();
      },
    );
  }

